from xml.sax.saxutils import escape, quoteattr

TTS_RATES = {
    "Neural": {"per_1m_chars": 15.0, "free_chars": 500_000},
    "HD": {"per_1m_chars": 30.0, "free_chars": 0},
    "Custom": {"per_1m_chars": 24.0, "free_chars": 0},
}

STT_RATES = {
    "RealTime": {"per_hour": 1.0, "free_hours": 5},
    "Batch": {"per_hour": 1.0, "free_hours": 5},
    "Custom": {"per_hour": 1.40, "free_hours": 0},
}

SYNTHESIS_NS = "http://www.w3.org/2001/10/synthesis"
MSTTS_NS = "https://www.w3.org/2001/mstts"


def tts_cost(chars, tier):
    if tier not in TTS_RATES:
        raise ValueError(f"unknown text-to-speech tier {tier!r}")
    billable = max(0, chars - TTS_RATES[tier]["free_chars"])
    return billable / 1_000_000 * TTS_RATES[tier]["per_1m_chars"]


def stt_cost(hours, tier):
    if tier not in STT_RATES:
        raise ValueError(f"unknown speech-to-text tier {tier!r}")
    billable = max(0, hours - STT_RATES[tier]["free_hours"])
    return billable * STT_RATES[tier]["per_hour"]


def build_ssml(text, voice, style=None, role=None, rate=None, pitch=None,
               voice_styles=None):
    locale = "-".join(voice.split("-")[:2])
    if not voice.endswith("Neural") or len(voice.split("-")) < 3:
        raise ValueError(f"{voice!r} is not a neural voice name")
    if style is not None:
        supported = (voice_styles or {}).get(voice, ())
        if style not in supported:
            raise ValueError(
                f"voice {voice!r} does not support the style {style!r}")

    body = escape(text)
    if rate is not None or pitch is not None:
        attributes = ""
        if rate is not None:
            attributes += f" rate={quoteattr(rate)}"
        if pitch is not None:
            attributes += f" pitch={quoteattr(pitch)}"
        body = f"<prosody{attributes}>{body}</prosody>"
    if style is not None or role is not None:
        attributes = ""
        if style is not None:
            attributes += f" style={quoteattr(style)}"
        if role is not None:
            attributes += f" role={quoteattr(role)}"
        body = f"<mstts:express-as{attributes}>{body}</mstts:express-as>"

    namespaces = f"xmlns={quoteattr(SYNTHESIS_NS)}"
    if style is not None or role is not None:
        namespaces += f" xmlns:mstts={quoteattr(MSTTS_NS)}"
    return (f"<speak version='1.0' {namespaces} xml:lang={quoteattr(locale)}>"
            f"<voice name={quoteattr(voice)}>{body}</voice></speak>")


def billable_characters(document):
    return len(document)
